                if (uncovered.length === 0) {
                  console.log(
                    chalk.green(
                      `  ✓ All ${covered.length} AC(s) have test coverage`,
                    ),
                  );
                } else {
                  console.log(
                    chalk.yellow(
                      `  Test coverage: ${covered.length}/${covered.length + uncovered.length} ACs covered`,
                    ),
                  );
                  console.log(
