          if (clearedFields.length > 0) {
            info(`Cleared fields: ${clearedFields.join(", ")}`);
          }
        });
      } catch (err) {
        error("Failed to reset task", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

