        const cancelReasonText = hadCancelReason
          ? ` (was cancelled: ${foundTask.closed_reason})`
          : "";

        // AC: @spec-task-reset ac-1 - Reset to pending, clear completion-related fields
        const clearedFields: string[] = [];
        const updatedTask: Task = {
          ...foundTask,
          status: "pending",
